    returning id into v_qid;

    insert into public.question_translations (question_id, locale, question_text)
    values (v_qid, 'pl', r.pl), (v_qid, 'en', r.en);

    insert into public.question_smaczki (question_id, position, is_active, side)
    values (v_qid, 1, true, r.s1s) returning id into v_sid;
    insert into public.question_smaczki_translations (smaczek_id, locale, text)
    values (v_sid, 'pl', r.s1pl), (v_sid, 'en', r.s1en);

    insert into public.question_smaczki (question_id, position, is_active, side)
    values (v_qid, 2, true, r.s2s) returning id into v_sid;
    insert into public.question_smaczki_translations (smaczek_id, locale, text)
    values (v_sid, 'pl', r.s2pl), (v_sid, 'en', r.s2en);

    insert into public.question_smaczki (question_id, position, is_active, side)
    values (v_qid, 3, true, r.s3s) returning id into v_sid;
    insert into public.question_smaczki_translations (smaczek_id, locale, text)
    values (v_sid, 'pl', r.s3pl), (v_sid, 'en', r.s3en);

    insert into public.question_vote_seeds (question_id, seed_yes_pct, seed_total)
    values (v_qid, 50, 0)
    on conflict (question_id) do nothing;
  end loop;
end
$mig$;
